func (v *Program) tfresh() bool          { return false }
func (v *Program) tsetFresh(bool)        {}
func (v *Program) tfield(name string) (any, bool) {
	switch name {
	case "Body":
		return func() any {
			if v.Body == nil {
				return nil
			}
			kids := make([]any, len(v.Body))
			for i, x := range v.Body {
				kids[i] = any(x)
			}
			return tlistOf(kids)
		}(), true
	}
	return nil, false
}

