func astNode(v any) *Node    { n, _ := v.(*Node); return n }
func astInt(v any) int       { i, _ := v.(int); return i }
func astString(v any) string { s, _ := v.(string); return s }
func astBool(v any) bool     { x, _ := v.(bool); return x }
func astPtrInt(v any) *int {
	if i, ok := v.(int); ok {
		return &i
	}
	return nil
}
func astPtrString(v any) *string {
	if s, ok := v.(string); ok {
		return &s
	}
	return nil
}
func astPtrBool(v any) *bool {
	if x, ok := v.(bool); ok {
		return &x
	}
	return nil
}

// astNew returns a new zero value from the chunk *s.
func astNew[T any](s *[]T) *T {
	if len(*s) == 0 {
		*s = make([]T, 256)
	}
	v := &(*s)[0]
	*s = (*s)[1:]
	return v
}

// astSlice returns a slice of n zero values from the chunk *s. Its capacity is n, so appending
// to it does not overwrite other slices.
func astSlice[T any](s *[]T, n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(*s) < n {
		*s = make([]T, 1024)
	}
	v := (*s)[:n:n]
	*s = (*s)[n:]
	return v
}

func (a *astConv) toMatch(n *Node) *Match {
	if n == nil || n.Type() != "Match" {
		return nil
	}
	v := astNew(&a.match)
	*v = Match{Span: Span{int(n.Start), int(n.End)}, Text: n.Text}
	return v
}

func (a *astConv) toError(n *Node) *Error {
	if n == nil || n.Type() != "Error" {
		return nil
	}
	msg, _ := n.Field("message").(string)
	v := astNew(&a.error)
	*v = Error{Span: Span{int(n.Start), int(n.End)}, Text: n.Text, Message: msg}
	return v
}

// anyValue converts a value of a statically unknown type into the typed value of its type (CST
// nodes stay *Node).
func (a *astConv) anyValue(v any) any {
	n, ok := v.(*Node)
	if !ok || n == nil {
		return v
	}
	switch n.Type() {
	case "Match":
		return a.toMatch(n)
	case "Error":
		return a.toError(n)
	case "Bool":
		return a.toBool(n)
	case "Ident":
		return a.toIdent(n)
	case "Number":
		return a.toNumber(n)
	case "String":
		return a.toString(n)
	case "ArrayLit":
		return a.toArrayLit(n)
	case "Assign":
		return a.toAssign(n)
	case "Binary":
		return a.toBinary(n)
	case "Block":
		return a.toBlock(n)
	case "Call":
		return a.toCall(n)
	case "Cond":
		return a.toCond(n)
	case "ExprStmt":
		return a.toExprStmt(n)
	case "Func":
		return a.toFunc(n)
	case "If":
		return a.toIf(n)
	case "Index":
		return a.toIndex(n)
	case "Let":
		return a.toLet(n)
	case "Member":
		return a.toMember(n)
	case "Program":
		return a.toProgram(n)
	case "Return":
		return a.toReturn(n)
	case "Unary":
		return a.toUnary(n)
	case "While":
		return a.toWhile(n)
	}
	return n
}

