// keyword, called as by invokePlain
func (p *parser) q18() (*Node, bool) {
	start, rec, trail := p.pos, len(p.recovered), len(p.trail)
	prevEnv, prevCut := p.env, p.cut
	p.cut = false
	p.depth++
	if p.depth > maxDepth {
		p.tooDeep()
	}
	v, ok := p.e546()
	p.depth--
	p.cut = prevCut
	p.trail = p.trail[:trail]
	if ok {
		v = nil
	} else {
		p.pos = start
		p.recovered = p.recovered[:rec]
	}
	p.env = prevEnv
	return v, ok
}

